import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Filter out near-duplicates based on correlation
    correlated_pairs = set()
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if abs(np.corrcoef(feats.x[:, i], feats.x[:, j])[0,1]) >= 0.6:
                correlated_pairs.add((min(fid1, fid2), max(fid1, fid2)))

    # Select features with strong t-statistics
    t_stats = []
    for i, fid in enumerate(feats.ids):
        y0 = feats.x[feats.y == 0, i]
        y1 = feats.x[feats.y == 1, i]
        t_stat, _ = stats.ttest_ind(y0, y1, equal_var=False)
        t_stats.append((abs(t_stat), fid))

    # Sort by t-statistic magnitude
    t_stats.sort(reverse=True)

    # Build list of candidate features avoiding near-duplicates
    candidates = []
    used_ids = set()
    for _, fid in t_stats:
        if any(fid in pair for pair in correlated_pairs):
            # Check if any member of correlated pair is already selected
            skip = False
            for pair in correlated_pairs:
                if fid in pair and any(member in used_ids for member in pair):
                    skip = True
                    break
            if not skip:
                candidates.append(fid)
                used_ids.add(fid)
        else:
            candidates.append(fid)
            used_ids.add(fid)

    # If no strong signals, return empty design
    if len(candidates) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top candidates to be drivers (at most MAX_DRIVERS)
    drivers = tuple(candidates[:MAX_DRIVERS])

    # For logistic regression, include all features with strong associations
    columns = tuple(candidates[:10])  # Include top 10 for regression

    # Identify potential interactions among top features
    products = []
    for i, fid1 in enumerate(columns):
        for j, fid2 in enumerate(columns[i+1:], i+1):
            # Add interaction terms if they're not too correlated
            corr = np.corrcoef(feats.x[:, feats.column(fid1)], 
                              feats.x[:, feats.column(fid2)])[0,1]
            if abs(corr) < 0.6:
                products.append((fid1, fid2))

    # Create weighted score using top features
    loadings = {}
    for i, fid in enumerate(columns):
        loadings[fid] = 1.0 / (i + 1)  # Simple inverse rank weighting

    return Design(drivers=drivers, columns=columns, products=tuple(products), loadings=loadings)
